//! Options: the tmux 3.8 options table, typed values, the trees they live in
//! and `set-option` / `show-options` as pure functions.
//!
//! - [`table`]: every option (options-table.c), generated by
//!   `options/gen_table.sh`: 183 table entries plus the 89 hooks.
//! - [`Value`] / [`OptionValue`]: what `set` makes of text and how it prints
//!   (options.c `options_from_string`, `options_value_to_string`).
//! - [`Options`]: one tree (`struct options`); [`OptionsStore`]: all of them,
//!   with tmux's parent links (pane -> window -> global window, session ->
//!   global session, server) and lookup with inheritance.
//! - [`apply_set`]: `set-option`, `set-window-option`, `set-hook`
//!   (cmd-set-option.c). [`apply_show`]: `show-options`,
//!   `show-window-options`, `show-hooks` (cmd-show-options.c). The server
//!   resolves `-t` to a [`Target`] and supplies format expansion through
//!   [`OptionHost`]; everything else happens here.
//!
//! Server start (tmux.c:524-553) is [`OptionsStore::new`] with [`Defaults`]:
//! the table defaults, then `default-shell` from `$SHELL`, `editor` from
//! `$VISUAL`/`$EDITOR` and vi keys when that editor's name contains `vi`.
//!
//! Known divergences:
//!
//! - `set-hook -B` and `show-hooks -B` (monitor hooks) are not handled
//!   here; they return [`OptionError::Unsupported`]. Monitors are server
//!   state.
//! - `set -U` on a window option also unsets it in the target window's
//!   panes, `-g` included, as tmux does. With no target window tmux
//!   dereferences a missing window (cmd-set-option.c:328); this skips the
//!   panes.

mod set;
mod show;
mod table;
mod value;

#[cfg(test)]
mod golden;

use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::fmt;

pub use set::{SetOutcome, apply_set};
pub use show::apply_show;
pub use table::{ArrayKey, DefaultValue, Kind, Level, OptionDef, Scope, StringCheck, find, table};
pub use value::{OptionValue, Value};

use crate::cmd::ConfigEnv;
use crate::colour::BadColour;
use crate::ids::{PaneId, SessionId, WindowId};
use crate::style::{InvalidColour, InvalidStyle};

/// What the environment contributes at server start (tmux.c:535-553). The
/// server reads these from its own environment; `Default` is what a server
/// started with `SHELL=/bin/sh` and no `EDITOR`/`VISUAL` gets, the setting
/// the goldens pin.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Defaults {
    /// `getshell()`: `$SHELL` if usable, else the passwd shell, else
    /// `/bin/sh`.
    pub shell: String,
    /// `$VISUAL`, else `$EDITOR`.
    pub editor: Option<String>,
    /// `default-terminal`: tmux's build-time `TMUX_TERM` (D7).
    pub term: String,
}

impl Defaults {
    /// tmux.c:543: `$VISUAL` wins over `$EDITOR`, even when empty.
    #[must_use]
    pub fn from_env(shell: String, visual: Option<String>, editor: Option<String>) -> Self {
        Self {
            shell,
            editor: visual.or(editor),
            ..Self::default()
        }
    }
}

impl Default for Defaults {
    fn default() -> Self {
        Self {
            shell: "/bin/sh".to_owned(),
            editor: None,
            term: "tmux-256color".to_owned(),
        }
    }
}

/// One option set in a tree: its table row (`None` for a user `@option`)
/// and its value.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Entry {
    pub def: Option<&'static OptionDef>,
    pub value: OptionValue,
}

impl Entry {
    /// `options_is_array`.
    #[must_use]
    pub fn is_array(&self) -> bool {
        self.def.is_some_and(|d| d.array)
    }

    /// `options_is_string`: user options and string-typed table options.
    #[must_use]
    pub fn is_string(&self) -> bool {
        self.def.is_none_or(OptionDef::is_string)
    }
}

/// One options tree (`struct options`): entries by name, in byte order
/// (tmux's RB tree uses `strcmp`).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Options {
    entries: BTreeMap<String, Entry>,
}

impl Options {
    /// `options_get_only`: this tree only, by name or an old spelling.
    #[must_use]
    pub fn get_only(&self, name: &str) -> Option<&Entry> {
        self.entries
            .get(name)
            .or_else(|| self.entries.get(table::map_name(name)))
    }

    fn get_only_mut(&mut self, name: &str) -> Option<&mut Entry> {
        let key = if self.entries.contains_key(name) {
            name
        } else {
            table::map_name(name)
        };
        self.entries.get_mut(key)
    }

    /// The entries, in name order.
    pub fn iter(&self) -> impl Iterator<Item = (&str, &Entry)> {
        self.entries.iter().map(|(k, v)| (k.as_str(), v))
    }

    fn insert(&mut self, name: &str, entry: Entry) {
        self.entries.insert(name.to_owned(), entry);
    }

    fn remove(&mut self, name: &str) {
        self.entries.remove(name);
    }

    /// `options_default`: put `def`'s default in this tree.
    fn set_default(&mut self, def: &'static OptionDef, term: &str) {
        self.insert(
            def.name,
            Entry {
                def: Some(def),
                value: value::default_value(def, term),
            },
        );
    }
}

/// Which options tree.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum TreeId {
    /// `global_options`.
    Server,
    /// `global_s_options`.
    GlobalSession,
    /// `global_w_options`.
    GlobalWindow,
    Session(SessionId),
    Window(WindowId),
    Pane(PaneId),
}

impl TreeId {
    /// One of the three trees created at start, which hold every option
    /// of their scope (`-u` resets them to the default instead of removing).
    #[must_use]
    pub fn is_global(self) -> bool {
        matches!(
            self,
            Self::Server | Self::GlobalSession | Self::GlobalWindow
        )
    }
}

/// Every options tree of a server, with the parent links tmux keeps.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct OptionsStore {
    server: Options,
    global_session: Options,
    global_window: Options,
    sessions: HashMap<SessionId, Options>,
    windows: HashMap<WindowId, Options>,
    panes: HashMap<PaneId, Options>,
    /// A pane's parent tree is its window's (`options_set_parent` when a
    /// pane moves, cmd-join-pane.c:506).
    pane_window: HashMap<PaneId, WindowId>,
    /// User options set with `set-hook` (`hooks_add_event`), which
    /// `show-options` hides without `-H`.
    hook_events: BTreeSet<String>,
    /// `TMUX_TERM`, the default `-u` restores to `default-terminal`.
    term: String,
}

static EMPTY: Options = Options {
    entries: BTreeMap::new(),
};

impl OptionsStore {
    /// The three global trees as tmux builds them at start (tmux.c:524-553).
    #[must_use]
    pub fn new(defaults: &Defaults) -> Self {
        let mut store = Self {
            server: Options::default(),
            global_session: Options::default(),
            global_window: Options::default(),
            sessions: HashMap::new(),
            windows: HashMap::new(),
            panes: HashMap::new(),
            pane_window: HashMap::new(),
            hook_events: BTreeSet::new(),
            term: defaults.term.clone(),
        };
        for def in table::table() {
            match def.scope {
                Scope::Server => store.server.set_default(def, &defaults.term),
                Scope::Session => store.global_session.set_default(def, &defaults.term),
                Scope::Window | Scope::WindowPane => {
                    store.global_window.set_default(def, &defaults.term);
                }
            }
        }
        let set = |tree: &mut Options, name: &str, value: Value| {
            if let Some(e) = tree.get_only_mut(name) {
                e.value = OptionValue::Single(value);
            }
        };
        set(
            &mut store.global_session,
            "default-shell",
            Value::String(defaults.shell.clone()),
        );
        if let Some(editor) = &defaults.editor {
            set(&mut store.server, "editor", Value::String(editor.clone()));
            let base = editor.rsplit('/').next().unwrap_or(editor);
            // options_table_mode_keys_list: emacs, vi.
            let keys = Value::Choice(usize::from(base.contains("vi")));
            set(&mut store.global_session, "status-keys", keys.clone());
            set(&mut store.global_window, "mode-keys", keys);
        }
        store
    }

    /// A new session's tree, empty, under the global session options.
    pub fn add_session(&mut self, id: SessionId) {
        self.sessions.insert(id, Options::default());
    }

    pub fn remove_session(&mut self, id: SessionId) {
        self.sessions.remove(&id);
    }

    pub fn add_window(&mut self, id: WindowId) {
        self.windows.insert(id, Options::default());
    }

    pub fn remove_window(&mut self, id: WindowId) {
        self.windows.remove(&id);
    }

    /// A new pane's tree, under its window's.
    pub fn add_pane(&mut self, id: PaneId, window: WindowId) {
        self.panes.insert(id, Options::default());
        self.pane_window.insert(id, window);
    }

    /// The pane moved to another window; its tree now inherits from there.
    pub fn move_pane(&mut self, id: PaneId, window: WindowId) {
        self.pane_window.insert(id, window);
    }

    pub fn remove_pane(&mut self, id: PaneId) {
        self.panes.remove(&id);
        self.pane_window.remove(&id);
    }

    /// A tree; one the store does not know is empty.
    #[must_use]
    pub fn tree(&self, id: TreeId) -> &Options {
        match id {
            TreeId::Server => &self.server,
            TreeId::GlobalSession => &self.global_session,
            TreeId::GlobalWindow => &self.global_window,
            TreeId::Session(s) => self.sessions.get(&s).unwrap_or(&EMPTY),
            TreeId::Window(w) => self.windows.get(&w).unwrap_or(&EMPTY),
            TreeId::Pane(p) => self.panes.get(&p).unwrap_or(&EMPTY),
        }
    }

    fn tree_mut(&mut self, id: TreeId) -> &mut Options {
        match id {
            TreeId::Server => &mut self.server,
            TreeId::GlobalSession => &mut self.global_session,
            TreeId::GlobalWindow => &mut self.global_window,
            TreeId::Session(s) => self.sessions.entry(s).or_default(),
            TreeId::Window(w) => self.windows.entry(w).or_default(),
            TreeId::Pane(p) => self.panes.entry(p).or_default(),
        }
    }

    /// The tree `id` inherits from.
    #[must_use]
    pub fn parent(&self, id: TreeId) -> Option<TreeId> {
        match id {
            TreeId::Server | TreeId::GlobalSession | TreeId::GlobalWindow => None,
            TreeId::Session(_) => Some(TreeId::GlobalSession),
            TreeId::Window(_) => Some(TreeId::GlobalWindow),
            TreeId::Pane(p) => Some(
                self.pane_window
                    .get(&p)
                    .map_or(TreeId::GlobalWindow, |w| TreeId::Window(*w)),
            ),
        }
    }

    /// `options_get`: the entry in `id` or the nearest ancestor that has it.
    #[must_use]
    pub fn get(&self, id: TreeId, name: &str) -> Option<&Entry> {
        let mut at = Some(id);
        while let Some(t) = at {
            if let Some(e) = self.tree(t).get_only(name) {
                return Some(e);
            }
            at = self.parent(t);
        }
        None
    }

    /// The panes whose tree inherits from window `w`.
    fn panes_of(&self, w: WindowId) -> Vec<PaneId> {
        let mut panes: Vec<PaneId> = self
            .pane_window
            .iter()
            .filter(|(_, pw)| **pw == w)
            .map(|(p, _)| *p)
            .collect();
        panes.sort_unstable();
        panes
    }

    /// Whether `set-hook` has made `name` a hook event.
    #[must_use]
    pub fn is_hook_event(&self, name: &str) -> bool {
        self.hook_events.contains(name)
    }

    /// An option as a format variable (`format_find`, format.c:4624-4640):
    /// `name` or `name[key]`, searched in the server options, then the
    /// pane, window, global window, session and global session trees, each
    /// with inheritance. Flags read as `1`/`0`.
    #[must_use]
    pub fn format_value(&self, name: &str, target: &Target) -> Option<String> {
        let (base, key) = table::parse_name(name)?;
        let mut trees = vec![TreeId::Server];
        trees.extend(target.pane.map(TreeId::Pane));
        trees.extend(target.window.map(TreeId::Window));
        trees.push(TreeId::GlobalWindow);
        trees.extend(target.session.map(TreeId::Session));
        trees.push(TreeId::GlobalSession);
        trees.into_iter().find_map(|t| {
            self.get(t, base)
                .map(|e| e.value.to_text(e.def, key.as_ref(), true))
        })
    }
}

/// What `-t` resolved to (`struct cmd_find_state`): the session, window and
/// pane a command acts on, any of which may be missing (`CMD_FIND_CANFAIL`).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Target {
    pub session: Option<SessionId>,
    pub window: Option<WindowId>,
    pub pane: Option<PaneId>,
}

/// What `set` and `show` need from the server.
pub trait OptionHost {
    /// `format_single_from_target`: expand `template` against the command's
    /// target, with `extra` variables on top (`show-options -F` adds the
    /// `option_*` ones). Options read through `store`.
    fn expand(&mut self, store: &OptionsStore, template: &str, extra: &[(&str, String)]) -> String;
    /// The global environment, for `$VAR` in command options
    /// (`cmd_parse_from_string`).
    fn config_env(&mut self) -> &mut dyn ConfigEnv;
    /// `checkshell` (tmux.c:98): absolute, executable, not tmux itself.
    fn usable_shell(&self, path: &str) -> bool;
}

/// Why `set` or `show` failed. `Display` is tmux's message.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum OptionError {
    /// `set-hook` with no hook name.
    MissingArgument,
    /// `set-hook -E` with more than one argument.
    TooManyArguments,
    /// `set-hook -E` with a name that is not `@...`.
    EventName,
    InvalidOption(String),
    AmbiguousOption(String),
    NoSuchSession(String),
    NoCurrentSession,
    NoSuchWindow(String),
    NoCurrentWindow,
    NoSuchPane(String),
    NoCurrentPane,
    NotAnArray(String),
    AlreadySet(String),
    EmptyValue,
    /// `value is invalid: x`, `value is too small: x`, ... (options.c:1319).
    ValueIs {
        why: &'static str,
        value: String,
    },
    /// A flag that is not on/off/yes/no/1/0.
    BadValue(String),
    /// A choice that is not one of the names.
    UnknownValue(String),
    BadKey(String),
    BadColour(BadColour),
    InvalidColour(InvalidColour),
    InvalidStyle(InvalidStyle),
    NotSuitableShell(String),
    /// A command option's text did not parse: the parser's message.
    Command(String),
    Other(&'static str),
    /// Something tmux does that vtmux does not do here.
    Unsupported(&'static str),
}

impl fmt::Display for OptionError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::MissingArgument => f.write_str("missing argument"),
            Self::TooManyArguments => f.write_str("too many arguments"),
            Self::EventName => f.write_str("event name must start with @"),
            Self::InvalidOption(s) => write!(f, "invalid option: {s}"),
            Self::AmbiguousOption(s) => write!(f, "ambiguous option: {s}"),
            Self::NoSuchSession(s) => write!(f, "no such session: {s}"),
            Self::NoCurrentSession => f.write_str("no current session"),
            Self::NoSuchWindow(s) => write!(f, "no such window: {s}"),
            Self::NoCurrentWindow => f.write_str("no current window"),
            Self::NoSuchPane(s) => write!(f, "no such pane: {s}"),
            Self::NoCurrentPane => f.write_str("no current pane"),
            Self::NotAnArray(s) => write!(f, "not an array: {s}"),
            Self::AlreadySet(s) => write!(f, "already set: {s}"),
            Self::EmptyValue => f.write_str("empty value"),
            Self::ValueIs { why, value } => write!(f, "value is {why}: {value}"),
            Self::BadValue(s) => write!(f, "bad value: {s}"),
            Self::UnknownValue(s) => write!(f, "unknown value: {s}"),
            Self::BadKey(s) => write!(f, "bad key: {s}"),
            Self::BadColour(e) => e.fmt(f),
            Self::InvalidColour(e) => e.fmt(f),
            Self::InvalidStyle(e) => e.fmt(f),
            Self::NotSuitableShell(s) => write!(f, "not a suitable shell: {s}"),
            Self::Command(s) => f.write_str(s),
            Self::Other(s) => f.write_str(s),
            Self::Unsupported(s) => write!(f, "not supported in vtmux yet: {s}"),
        }
    }
}

impl std::error::Error for OptionError {}

/// `options_scope_from_flags` (options.c:1095) and `options_scope_from_name`
/// (options.c:1027): which tree a command acts on.
fn resolve_tree(
    def: Option<&OptionDef>,
    args: &crate::cmd::Args,
    window_cmd: bool,
    target: &Target,
) -> Result<(TreeId, Level), OptionError> {
    let given = args.value('t');
    let global = args.flag('g');
    let session = || match target.session {
        _ if global => Ok((TreeId::GlobalSession, Level::Session)),
        Some(s) => Ok((TreeId::Session(s), Level::Session)),
        None => Err(given.map_or(OptionError::NoCurrentSession, |t| {
            OptionError::NoSuchSession(t.to_owned())
        })),
    };
    let window = || match target.window {
        _ if global => Ok((TreeId::GlobalWindow, Level::Window)),
        Some(w) => Ok((TreeId::Window(w), Level::Window)),
        None => Err(given.map_or(OptionError::NoCurrentWindow, |t| {
            OptionError::NoSuchWindow(t.to_owned())
        })),
    };
    let pane = || match target.pane {
        Some(p) => Ok((TreeId::Pane(p), Level::Pane)),
        None => Err(given.map_or(OptionError::NoCurrentPane, |t| {
            OptionError::NoSuchPane(t.to_owned())
        })),
    };
    match def.map(|d| d.scope) {
        None => {
            if args.flag('s') {
                Ok((TreeId::Server, Level::Server))
            } else if args.flag('p') {
                pane()
            } else if window_cmd || args.flag('w') {
                window()
            } else {
                session()
            }
        }
        Some(Scope::Server) => Ok((TreeId::Server, Level::Server)),
        Some(Scope::Session) => session(),
        Some(Scope::WindowPane) if args.flag('p') => pane(),
        Some(Scope::Window | Scope::WindowPane) => window(),
    }
}
